INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('20fa7591-9bee-4671-b2ae-250b8ce86126','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"eae9f0d6-84cb-4dcf-a8d1-35ed645aae5c\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"8b4ed83d-8537-4756-a253-2b86958183b0\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"02bf6bd4-b91c-4150-afc3-49692727a21f\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"8b4ed83d-8537-4756-a253-2b86958183b0\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"7d90ff74-49db-4917-8d9d-5b7cc24b2f2f\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"7e4007ca-b63c-45d0-a01a-a38f80c0f558\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"7d90ff74-49db-4917-8d9d-5b7cc24b2f2f\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"560d4f96-68e4-4d42-a3a6-58d9b57badd6\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"1ab8f941-3b26-4ad1-9b10-117419daa213\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"fc0d2011-1913-4218-9b9a-32ecfd3f4b22\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"1ab8f941-3b26-4ad1-9b10-117419daa213\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"5e7c64bf-509f-427e-8271-65f17926c56a\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"dc569608-948b-46cc-91a9-6e3bb88f7403\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"d034717a-5eea-4d66-94f5-997d07094643\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"dc569608-948b-46cc-91a9-6e3bb88f7403\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"3ca631e3-1283-4d04-b7f5-85aa6c2ee607\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"bde67311-9f34-49b7-961c-51f329dfef9f\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"e231f34f-9623-4cce-b562-40e00e4a29c7\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"6d6909c8-596d-4841-8383-31f0042d3daf\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"e231f34f-9623-4cce-b562-40e00e4a29c7\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"d7b740fe-d243-4c56-8745-cc81274214e5\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"ca7a9481-a5d8-4ffa-865e-b2ee3bc01442\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"f789f2b6-31ae-4fb3-8601-66617692b386\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"ca7a9481-a5d8-4ffa-865e-b2ee3bc01442\",\"triggerValues\":[\"no\"]}},{\"id\":\"12258e62-c0e0-47b9-8916-bf68d4f554fc\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"73a0119f-6903-49c3-aade-7d4b2e33a0af\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"429a83e7-78f3-44fd-b1ed-f949c8621ab3\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"8762ab14-5680-4a09-8c0b-5a2752286653\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"1678861d-c1eb-4b2c-a51a-3317c0e49996\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"429a83e7-78f3-44fd-b1ed-f949c8621ab3\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"69694637-c5ca-49a4-b109-56b8576e091e\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"0e823d6d-c75b-44b3-a9c5-a205e6fdcada\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"72a3c9ee-1c5d-4e66-9cc9-dbf96ceab7d3\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0e823d6d-c75b-44b3-a9c5-a205e6fdcada\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"06cad055-8b6c-4bc4-8eb6-1746a3b7dad9\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"a3ad6b52-d4f1-42ba-8287-74495fa9dc9d\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"06cad055-8b6c-4bc4-8eb6-1746a3b7dad9\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"e095ffc9-789a-45fe-b380-f6aa8ffd7f4b\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"e5acce17-ff5a-46e9-aea1-190e7bd9b503\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"3295eb76-0f20-49af-b857-8d3fa633ad0d\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"2a6d3191-d889-442f-8450-3340352e00e8\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"3295eb76-0f20-49af-b857-8d3fa633ad0d\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"b367d32a-22d3-44f4-944c-98c328637b7d\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T13:51:03.789Z','2026-10-21T13:51:03.789Z','usine'),
('442a3185-7538-43e0-b106-865dbf2942e7','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"4880e660-3486-4fe3-8fb0-c709b0f2a49f\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"034ad8a2-9cf7-4339-a154-42b40f23b48d\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"11aa764c-8e54-460c-8841-4cbd4da63b31\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"034ad8a2-9cf7-4339-a154-42b40f23b48d\",\"triggerValues\":[\"no\"]}},{\"id\":\"cdb8dc41-2a0f-4484-be63-4350985c7e06\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"59f842ad-4b8b-4e16-8ac0-ffd5e5ec77d5\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"cdb8dc41-2a0f-4484-be63-4350985c7e06\",\"triggerValues\":[\"yes\"]}},{\"id\":\"c2285d43-e98f-40fb-bc82-dd1a4b766197\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"75b8c5d1-4528-4a74-8a25-b2f9ace81e85\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"c2285d43-e98f-40fb-bc82-dd1a4b766197\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"1375539f-6697-419e-85a2-fae0244fc2a6\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"cc0c91db-d368-46ee-854f-e92f885464d7\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"f5dd7010-3409-4068-bd6c-3b9e3bded0e1\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"cc0c91db-d368-46ee-854f-e92f885464d7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"cfa25abc-d43b-4c05-8ae7-4416abcfcbf0\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"cc0c91db-d368-46ee-854f-e92f885464d7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"f39012cd-9c56-4846-9b31-94efdb272b67\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"cc0c91db-d368-46ee-854f-e92f885464d7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"7ae864ce-94e5-4a1f-868a-4da789d231b5\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"5d902941-6887-4647-b707-d03d23f52372\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"7ae864ce-94e5-4a1f-868a-4da789d231b5\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"d0a8b7ba-fe6e-48cc-9534-81956ca2b3b4\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"772b7aec-34ab-4583-b132-119621cd4079\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"121e5eda-052f-4efe-8293-3c044076ba5f\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"772b7aec-34ab-4583-b132-119621cd4079\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"cee11468-01ad-488f-b50d-2249a3efd6d0\",\"text\":\"Les remises accordées sont-elles validées officiellement avant application ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"f5ccaf4f-ea60-41c3-ad46-5c980c738f24\",\"text\":\"Les retours clients sont-ils traités selon la procédure (déclaration, validation direction) ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"3b2bc65f-f9ed-4281-a64c-7835e1dc8e12\",\"text\":\"Précisez les retours en attente et l\'origine du blocage\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"f5ccaf4f-ea60-41c3-ad46-5c980c738f24\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"cec7e12a-6576-4532-9734-d7eb6d8fea92\",\"label\":\"Organisation et ressources humaines\",\"questions\":[{\"id\":\"42b12df7-45b3-4760-8b69-11646142dd64\",\"text\":\"Les effectifs administratifs sont-ils suffisants pour les tâches du dépôt ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"2b50b3fb-d24a-4708-8d56-fb1baf4e14b2\",\"text\":\"Précisez les tâches impactées et les recommandations (recrutement, réorganisation…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"42b12df7-45b3-4760-8b69-11646142dd64\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"d739a54d-6adc-453b-8242-668ef6a8cdcd\",\"text\":\"Un organigramme clair et une répartition des tâches sont-ils en place ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true}]},{\"id\":\"78a39821-301d-4fab-98a6-525198293033\",\"label\":\"Suivi balance client, recouvrement et effets\",\"questions\":[{\"id\":\"3391294a-3215-4bb6-8dd9-10c7ff73159a\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"49d338d3-b1cf-4853-a4b8-3e2ba67c8ece\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"b8615e4b-6493-4fd4-9cb6-986fd0663d6a\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"3391294a-3215-4bb6-8dd9-10c7ff73159a\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"56ddba01-c1b4-4a2d-9bd6-2e0bb919fe04\",\"text\":\"La gestion des effets (traites, échéances) est-elle rigoureuse et à jour ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T13:51:03.795Z','2026-10-21T13:51:03.795Z','depot'),
('513b61ff-a6d0-487d-a6af-b286f7ebd90a','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"9ff44589-aae2-4827-9830-56180116147d\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"91a8e137-5457-4dcb-9c36-58bfef034971\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"4ce1159f-dd8e-4c8c-82e6-aab8d0cd1424\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"91a8e137-5457-4dcb-9c36-58bfef034971\",\"triggerValues\":[\"no\"]}},{\"id\":\"466da0ae-668c-439f-a4eb-27e42e39746c\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"680a8583-a876-4a28-9b42-fb0ae0652987\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"466da0ae-668c-439f-a4eb-27e42e39746c\",\"triggerValues\":[\"no\"]}},{\"id\":\"f6745005-3797-416f-89fa-ff12299df528\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"efb719e2-aea5-414b-a42a-9a8bce69f293\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"f6745005-3797-416f-89fa-ff12299df528\",\"triggerValues\":[\"no\"]}},{\"id\":\"9ae9fd94-464a-44cc-9ff3-1b54ccf7bb31\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"c8667243-924b-4e5a-9b54-a9be6a477a39\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"9ae9fd94-464a-44cc-9ff3-1b54ccf7bb31\",\"triggerValues\":[\"no\"]}},{\"id\":\"9e9f603d-251d-44cf-9b7d-9a9b3831984f\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"9c92ffe5-5467-42b9-bec2-dee644c0ecdb\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"2699a744-493c-4ba8-9bad-84c9b2d3fb1b\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"9c92ffe5-5467-42b9-bec2-dee644c0ecdb\",\"triggerValues\":[\"no\"]}},{\"id\":\"7228b13d-a4da-4851-8da7-9fe8be8f3527\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"4b20cd96-4b35-44f5-b637-542be6c1c629\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"876958c9-a463-4068-a96d-23e49b442902\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"e3d9bb01-f8a7-406b-84f4-d737479cb333\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"876958c9-a463-4068-a96d-23e49b442902\",\"triggerValues\":[\"no\"]}},{\"id\":\"b3ff81c9-e608-4420-8854-db087432f3aa\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"339085e3-da92-4dfe-8c86-2649b21a910f\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b3ff81c9-e608-4420-8854-db087432f3aa\",\"triggerValues\":[\"no\"]}},{\"id\":\"bc92f24d-fb9b-44d0-a10c-848f77793abc\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"5d6b0a98-ec10-46c4-bc91-d496a1be8505\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"bc92f24d-fb9b-44d0-a10c-848f77793abc\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"fcc515e8-c85e-4412-bee7-c1ca97e007b0\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"2f3f15fd-2689-4c03-ab8d-abe0be324058\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"bf4ac3e8-92f0-471e-a01e-d67f63ecd114\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"2f3f15fd-2689-4c03-ab8d-abe0be324058\",\"triggerValues\":[\"no\"]}},{\"id\":\"900c5eb5-59cc-4df7-89c5-9d708b054c7a\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"2f3f15fd-2689-4c03-ab8d-abe0be324058\",\"triggerValues\":[\"no\"]}},{\"id\":\"e426edc0-d2f8-4de2-849a-7d92045d0823\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"6d14f26e-8f57-4b05-a257-cf8c74c4cf15\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"e426edc0-d2f8-4de2-849a-7d92045d0823\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"8d83cf1f-350d-4012-ba90-d001b977280d\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"b91d7c9b-5d3b-4a55-bf63-b6c3364de543\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"3a90014f-499b-453a-a641-0c931dcc4255\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b91d7c9b-5d3b-4a55-bf63-b6c3364de543\",\"triggerValues\":[\"yes\"]}},{\"id\":\"d8347e41-3876-42b0-968c-b56dd6a2b02d\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b91d7c9b-5d3b-4a55-bf63-b6c3364de543\",\"triggerValues\":[\"yes\"]}},{\"id\":\"8fad4f19-96f8-48eb-aee6-e2aff64d1722\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b91d7c9b-5d3b-4a55-bf63-b6c3364de543\",\"triggerValues\":[\"yes\"]}},{\"id\":\"331761e3-207f-4d4b-b06d-b2900507c8a1\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"b91d7c9b-5d3b-4a55-bf63-b6c3364de543\",\"triggerValues\":[\"yes\"]}}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T13:51:03.798Z','2026-10-21T13:51:03.798Z','container');
